function validCloudConfig(){return window.supabase && SUPABASE_URL.startsWith('https://') && !SUPABASE_URL.includes('COLE_') && SUPABASE_ANON_KEY.length>20 && !SUPABASE_ANON_KEY.includes('COLE_')}
