function current(){return db.championships.find(c=>c.id===db.selected)||db.championships[0]}function stageById(c,id){return c.stages.find(s=>s.id===id)}
function teamsOf(s){if(s.type==='knockout')return (s.teams||[]).map(t=>({...t,groupId:'',groupName:s.name}));return (s.groups||[]).flatMap(g=>g.teams.map(t=>({...t,groupId:g.id,groupName:g.name})))}
